import (
	"errors"
	"fmt"
	"sync"
	"time"
)

var ErrSplitBrainPrevented = errors.New("storage: fencing token is stale, potential split-brain detected")

type FencedStorage struct {
	mu                 sync.Mutex
	committedData      string
	lastCommittedToken uint64
}

func (s *FencedStorage) CommitData(token uint64, data string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if token < s.lastCommittedToken {
		return fmt.Errorf("%w (attempted token: %d, storage current token: %d)",
			ErrSplitBrainPrevented, token, s.lastCommittedToken)
	}

	s.lastCommittedToken = token
	s.committedData = data
	return nil
}

type CentralLockServer struct {
	mu      sync.Mutex
	counter uint64
}

func (l *CentralLockServer) GrantLock() uint64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.counter++
	return l.counter
}

func main() {
	lockServer := &CentralLockServer{counter: 99}
	storage := &FencedStorage{lastCommittedToken: 0}

	// 1. Worker A получает блокировку
	tokenA := lockServer.GrantLock()
	fmt.Printf("[T0] Worker A acquired lock with Token: %d\n", tokenA)

	// 2. Worker A «замерзает» (freeze/pause)
	fmt.Println("[T1] Worker A crashes / experiences massive freeze...")

	// 3. Таймаут блокировки. Worker B получает лок
	tokenB := lockServer.GrantLock()
	fmt.Printf("[T2] Lock expired. Worker B acquired lock with Token: %d\n", tokenB)

	// 4. Worker B успешно сохраняет отчет
	err := storage.CommitData(tokenB, "FINAL_REPORT_V2_BY_WORKER_B")
	fmt.Printf("[T3] Worker B write result: err=%v (Storage token now: %d)\n", err, storage.lastCommittedToken)

	// 5. Worker A просыпается и пытается сохранить устаревший отчет
	fmt.Printf("[T4] Worker A recovers! Attempting commit with stale Token: %d...\n", tokenA)
	err = storage.CommitData(tokenA, "STALE_REPORT_V1_BY_WORKER_A")
	if errors.Is(err, ErrSplitBrainPrevented) {
		fmt.Printf("[T5] SUCCESS! Storage safely blocked Worker A: %v\n", err)
	} else {
		panic("Catastrophic failure: Stale write was accepted!")
	}

	fmt.Printf("\nFinal Preserved Storage Data: %q\n", storage.committedData)
	_ = time.Second
}

package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type CacheItem struct {
	Value     string
	ExpiresAt time.Time
}

type RaftCacheNode struct {
	id          string
	mu          sync.RWMutex
	isLeader    bool
	kvStore     map[string]CacheItem
	commitIndex uint64
}

func NewRaftCacheNode(id string, isLeader bool) *RaftCacheNode {
	return &RaftCacheNode{
		id:       id,
		isLeader: isLeader,
		kvStore:  make(map[string]CacheItem),
	}
}

func (n *RaftCacheNode) Write(key, value string, ttl time.Duration) error {
	n.mu.Lock()
	defer n.mu.Unlock()

	if !n.isLeader {
		return errors.New("ERR_NOT_LEADER: please redirect request to current raft leader")
	}

	n.commitIndex++
	n.kvStore[key] = CacheItem{
		Value:     value,
		ExpiresAt: time.Now().Add(ttl),
	}
	return nil
}

func (n *RaftCacheNode) ReadConsistent(key string) (string, error) {
	n.mu.RLock()
	defer n.mu.RUnlock()

	item, exists := n.kvStore[key]
	if !exists {
		return "", errors.New("key not found")
	}
	if time.Now().After(item.ExpiresAt) {
		return "", errors.New("key expired")
	}
	return item.Value, nil
}

// AuditLogger с валидацией Fencing Token
type CentralAuditStore struct {
	mu           sync.Mutex
	logs         []string
	highestToken uint64
}

func (a *CentralAuditStore) AppendLog(token uint64, entry string) error {
	a.mu.Lock()
	defer a.mu.Unlock()

	if token < a.highestToken {
		return fmt.Errorf("AUDIT_REJECTED: Stale token %d < highest %d", token, a.highestToken)
	}

	a.highestToken = token
	a.logs = append(a.logs, fmt.Sprintf("[Token:%d] %s", token, entry))
	return nil
}

type EtcdEvictorElection struct {
	currentLeader string
	termSeq       atomic.Uint64
}

func (e *EtcdEvictorElection) Campaign(nodeID string) (uint64, error) {
	token := e.termSeq.Add(1)
	e.currentLeader = nodeID
	return token, nil
}

func main() {
	fmt.Println("=== HA Distributed Cache with Raft & Fenced Evictor ===")

	// 1. Создаем кластер из 3 узлов
	node1 := NewRaftCacheNode("node-1", true)  // Leader
	node2 := NewRaftCacheNode("node-2", false) // Follower
	_ = node2

	// 2. Запись в Leader
	err := node1.Write("session:usr_99", "AUTH_TOKEN_ABC", 500*time.Millisecond)
	fmt.Printf("[Raft Leader] Write key status: err=%v\n", err)

	// Попытка записи в Follower (отказ)
	err = node2.Write("session:usr_99", "AUTH_TOKEN_ABC", 500*time.Millisecond)
	fmt.Printf("[Raft Follower] Direct write attempt: %v\n", err)

	// Чтение данных
	val, err := node1.ReadConsistent("session:usr_99")
	fmt.Printf("[Cache Read] key='session:usr_99', value='%s'\n", val)

	// 3. Выборы Evictor через etcd
	etcdElection := &EtcdEvictorElection{}
	auditDB := &CentralAuditStore{}

	// Node 1 выигрывает выборы эвиктора
	token1, _ := etcdElection.Campaign("node-1")
	fmt.Printf("\n[etcd Election] Node-1 elected as Evictor with Fencing Token: %d\n", token1)
	_ = auditDB.AppendLog(token1, "Evictor cleanup started by node-1")

	// Симуляция смены лидера эвиктора на Node-2
	token2, _ := etcdElection.Campaign("node-2")
	fmt.Printf("[etcd Election] Leader failover! Node-2 elected with Fencing Token: %d\n", token2)
	_ = auditDB.AppendLog(token2, "Evictor cleanup executed by node-2")

	// Старый эвиктор (Node-1) очнулся и пытается записать в аудит
	fmt.Println("[Node-1] Stale evictor trying to write audit log with Token", token1)
	err = auditDB.AppendLog(token1, "Stale cleanup log by node-1")
	if err != nil {
		fmt.Printf("[Audit Engine] SAFE: %v\n", err)
	}

	fmt.Println("\nFinal Audit Logs in DB:")
	for _, l := range auditDB.logs {
		fmt.Println(" ", l)
	}
	_ = context.Background()
}

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type JobItem struct {
	ID           string
	Payload      string
	FencingToken uint64
	AssignedTo   string
	Completed    bool
}

type JobCoordinatorMaster struct {
	nodeID       string
	isMaster     bool
	tasks        map[string]*JobItem
	tokenCounter atomic.Uint64
	mu           sync.Mutex
}

func NewJobCoordinatorMaster(nodeID string) *JobCoordinatorMaster {
	return &JobCoordinatorMaster{
		nodeID: nodeID,
		tasks:  make(map[string]*JobItem),
	}
}

func (m *JobCoordinatorMaster) SubmitJob(id, payload string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.tasks[id] = &JobItem{
		ID:           id,
		Payload:      payload,
		FencingToken: m.tokenCounter.Add(1),
	}
}

func (m *JobCoordinatorMaster) DispatchJob(id, workerID string) (uint64, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	task, exists := m.tasks[id]
	if !exists {
		return 0, fmt.Errorf("task %s not found", id)
	}

	task.FencingToken = m.tokenCounter.Add(1)
	task.AssignedTo = workerID
	return task.FencingToken, nil
}

func (m *JobCoordinatorMaster) CompleteJob(id, workerID string, token uint64) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	task, exists := m.tasks[id]
	if !exists {
		return fmt.Errorf("task %s not found", id)
	}

	if task.FencingToken != token {
		return fmt.Errorf("FENCING VIOLATION: Stale token %d != active %d", token, task.FencingToken)
	}

	task.Completed = true
	return nil
}

func main() {
	fmt.Println("=== Distributed Job Coordinator System (Leader + Raft + Locks) ===")

	master := NewJobCoordinatorMaster("coordinator-node-01")
	master.SubmitJob("etl-order-sync", "SELECT * FROM orders WHERE date = TODAY()")

	// Назначение задачи воркеру A с Fencing Token
	tokenA, err := master.DispatchJob("etl-order-sync", "worker-A")
	fmt.Printf("[Master] Dispatched 'etl-order-sync' to worker-A with Token %d (err: %v)\n", tokenA, err)

	// Воркер A завис. Мастер переназначает задачу воркеру B
	fmt.Println("[Master] Worker-A heartbeat lost! Reassigning job to worker-B...")
	tokenB, _ := master.DispatchJob("etl-order-sync", "worker-B")
	fmt.Printf("[Master] Re-dispatched to worker-B with new Token %d\n", tokenB)

	// Воркер B успешно завершает задачу
	err = master.CompleteJob("etl-order-sync", "worker-B", tokenB)
	fmt.Printf("[Master] Worker-B completion result: err=%v\n", err)

	// Оживший воркер A пытается сдать работу по старому токену
	err = master.CompleteJob("etl-order-sync", "worker-A", tokenA)
	fmt.Printf("[Master] Worker-A stale submission result: %v\n", err)

	fmt.Printf("\nCoordinator Cluster State: Task completed=%v, Final Token=%d\n",
		master.tasks["etl-order-sync"].Completed, master.tasks["etl-order-sync"].FencingToken)
	_ = context.Background()
	_ = time.Second
}

package main

import (
	"context"
	"fmt"
	"strings"
	"sync"
	"time"
)

type SharedNetworkFile struct {
	mu      sync.Mutex
	content []string
}

func (f *SharedNetworkFile) AppendChunk(lines []string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, l := range lines {
		f.content = append(f.content, l)
		time.Sleep(5 * time.Millisecond) // симуляция медленного сетевого I/O
	}
}

type EtcdConcurrencyMutex struct {
	mu    sync.Mutex
	queue chan struct{}
}

func NewEtcdConcurrencyMutex() *EtcdConcurrencyMutex {
	ch := make(chan struct{}, 1)
	ch <- struct{}{} // 1 доступный слот
	return &EtcdConcurrencyMutex{queue: ch}
}

func (m *EtcdConcurrencyMutex) Lock(ctx context.Context) error {
	select {
	case <-m.queue:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (m *EtcdConcurrencyMutex) Unlock(ctx context.Context) error {
	m.queue <- struct{}{}
	return nil
}

func RunFileWorker(id int, file *SharedNetworkFile, mutex *EtcdConcurrencyMutex, wg *sync.WaitGroup) {
	defer wg.Done()
	ctx := context.Background()

	for iter := 1; iter <= 2; iter++ {
		// 1. Захват распределенной блокировки etcd
		if err := mutex.Lock(ctx); err != nil {
			fmt.Printf("[Proc %d] Lock error: %v\n", id, err)
			return
		}

		// 2. Критическая секция: атомарная запись блока строк
		chunk := []string{
			fmt.Sprintf("=== START Process %d Block %d ===", id, iter),
			fmt.Sprintf("Process %d: writing payload record 1", id),
			fmt.Sprintf("Process %d: writing payload record 2", id),
			fmt.Sprintf("=== END Process %d Block %d ===", id, iter),
		}
		file.AppendChunk(chunk)

		// 3. Освобождение блокировки
		_ = mutex.Unlock(ctx)
		time.Sleep(10 * time.Millisecond)
	}
}

func main() {
	file := &SharedNetworkFile{}
	mutex := NewEtcdConcurrencyMutex()

	var wg sync.WaitGroup
	numProcs := 3

	fmt.Printf("Starting %d parallel processes coordinating file writes via etcd Mutex...\n\n", numProcs)
	wg.Add(numProcs)
	for i := 1; i <= numProcs; i++ {
		go RunFileWorker(i, file, mutex, &wg)
	}

	wg.Wait()

	fmt.Println("=== Final Shared File Content (Clean blocks without corruption) ===")
	for _, line := range file.content {
		if strings.HasPrefix(line, "===") {
			fmt.Println(line)
		} else {
			fmt.Println("  " + line)
		}
	}

	expectedLines := numProcs * 2 * 4
	if len(file.content) == expectedLines {
		fmt.Printf("\nSUCCESS: All %d lines written atomically without corruption!\n", expectedLines)
	}
}
